// ===========================================
// NODE 1: NORMALIZAR E VALIDAR MENSAGEM
// Aceita telefones E LIDs como identificadores
// ===========================================

const input = $input.first().json;
const body = input.body || input;
const event = body.event;
const payload = body.payload || {};

// Validações básicas
if (event !== 'message' && event !== 'message.any') {
  return [{ json: { skip: true, reason: 'not_message_event', event } }];
}

if (payload.fromMe === true) {
  return [{ json: { skip: true, reason: 'from_me' } }];
}

if (payload.isStatus || payload.broadcast) {
  return [{ json: { skip: true, reason: 'status_or_broadcast' } }];
}

// Valida timestamp (ignora mensagens > 120s)
const currentTime = Math.floor(Date.now() / 1000);
let timestamp = payload.timestamp || payload.t || payload._data?.t;
if (timestamp) {
  if (timestamp > 9999999999) timestamp = Math.floor(timestamp / 1000);
  const messageAge = currentTime - timestamp;
  if (messageAge > 120) {
    return [{ json: { skip: true, reason: 'old_message', age: messageAge } }];
  }
}

// Extrai chat_id - aceita telefones E LIDs
const _data = payload._data || {};
const info = _data.Info || {};

// Lista de campos para tentar (em ordem de prioridade)
const candidates = [
  payload.chatId,
  payload.from,
  info.RemoteJid,
  _data.RemoteJid,
  payload.participant
].filter(Boolean);

let chatId = null;
let isLid = false;

for (const candidate of candidates) {
  if (!candidate) continue;

  // Aceita LIDs diretamente
  if (candidate.includes('@lid')) {
    chatId = candidate;
    isLid = true;
    break;
  }

  // Aceita formatos @c.us e @s.whatsapp.net
  if (candidate.includes('@c.us') || candidate.includes('@s.whatsapp.net')) {
    chatId = candidate;
    break;
  }

  // Tenta extrair número puro
  let num = candidate.split('@')[0].split(':')[0];
  num = num.replace(/\D/g, '');

  if (num.length >= 8) {
    chatId = num + '@c.us';
    break;
  }
}

if (!chatId) {
  return [{ json: { skip: true, reason: 'no_chat_id_found' } }];
}

// Extrai o identificador (parte antes do @)
const phone = chatId.split('@')[0].split(':')[0];

// Extrai texto e metadata
const text = (payload.body || '').trim();
const messageId = payload.id || info.ID || `${phone}_${currentTime}`;
const msgType = payload.type || _data.Type || 'chat';
const customerName = info.PushName || payload.notifyName || '';

// Ignora mensagens vazias (exceto se for mídia)
if (!text && msgType === 'chat') {
  return [{ json: { skip: true, reason: 'empty_message' } }];
}

// Retorna dados normalizados - usa chat_id completo como identificador
return [{
  json: {
    skip: false,
    is_lid: isLid,
    normalized: {
      channel: 'whatsapp',
      phone: chatId,
      chat_id: chatId,
      text: text,
      message_id: messageId,
      timestamp: timestamp || currentTime,
      msg_type: msgType,
      customer_name: customerName
    },
    _raw: body
  }
}];

// ===========================================
// NODE 2: DEDUP + BUFFER
// ===========================================

const data = $input.first().json;
const phone = data.normalized.phone;
const text = data.normalized.text;
const messageId = data.normalized.message_id;
const timestamp = data.normalized.timestamp;

const BUFFER_WINDOW_MS = 3000;
const BUFFER_KEY = `buffer_${phone}`;
const DEDUP_KEY = `dedup_${messageId}`;

const $static = $getWorkflowStaticData('global');

if ($static[DEDUP_KEY]) {
  return [{ json: { skip: true, reason: 'duplicate_message', messageId } }];
}
$static[DEDUP_KEY] = Date.now();

Object.keys($static).forEach(key => {
  if (key.startsWith('dedup_') && Date.now() - $static[key] > 300000) {
    delete $static[key];
  }
});

if (!$static[BUFFER_KEY]) {
  $static[BUFFER_KEY] = {
    messages: [],
    first_timestamp: Date.now(),
    last_timestamp: Date.now()
  };
}

$static[BUFFER_KEY].messages.push({
  text: text,
  timestamp: timestamp,
  message_id: messageId
});
$static[BUFFER_KEY].last_timestamp = Date.now();

return [{
  json: {
    ...data,
    buffer: {
      phone: phone,
      messages_count: $static[BUFFER_KEY].messages.length,
      first_timestamp: $static[BUFFER_KEY].first_timestamp,
      last_timestamp: $static[BUFFER_KEY].last_timestamp,
      window_ms: BUFFER_WINDOW_MS
    }
  }
}];

// ===========================================
// NODE 3: CONSOLIDAR BUFFER
// ===========================================

const data = $input.first().json;
const phone = data.normalized.phone;
const BUFFER_KEY = `buffer_${phone}`;
const BUFFER_WINDOW_MS = 3000;

const $static = $getWorkflowStaticData('global');
const buffer = $static[BUFFER_KEY];

if (!buffer || buffer.messages.length === 0) {
  return [{
    json: {
      ...data,
      buffer: {
        combined_text: data.normalized.text,
        messages_count: 1,
        window_seconds: BUFFER_WINDOW_MS / 1000,
        texts: [data.normalized.text]
      }
    }
  }];
}

const timeSinceLastMessage = Date.now() - buffer.last_timestamp;
if (timeSinceLastMessage < BUFFER_WINDOW_MS) {
  return [{ json: { skip: true, reason: 'buffer_still_filling', time_since: timeSinceLastMessage } }];
}

const messages = buffer.messages;
const texts = messages.map(m => m.text).filter(t => t);
const combinedText = texts.join(' / ');

delete $static[BUFFER_KEY];

return [{
  json: {
    ...data,
    normalized: {
      ...data.normalized,
      text: combinedText
    },
    buffer: {
      combined_text: combinedText,
      messages_count: messages.length,
      window_seconds: BUFFER_WINDOW_MS / 1000,
      texts: texts
    }
  }
}];

// ===========================================
// NODE 4: ROUTER RULES-FIRST
// ===========================================

const data = $input.first().json;
const text = (data.buffer?.combined_text || data.normalized.text || '').toLowerCase().trim();
const messagesCount = data.buffer?.messages_count || 1;

const SAFE_PATTERNS = [
  /^[1-9]$/,
  /^[1-9][0-9]?$/,
  /^(sim|s|yes|y|ok|beleza|isso|confirmo|confirma|certo)$/i,
  /^(nao|não|n|no|cancela|cancelar|desistir)$/i,
  /^(pix|dinheiro|cartao|cartão|credito|crédito|debito|débito|cash|card)$/i,
  /^(entrega|delivery|retirada|retirar|buscar|pickup)$/i,
  /^r?\$?\s?\d{1,3}([.,]\d{2})?$/i,
  /^(voltar|volta|cancelar|sair|menu|cardapio|cardápio|ajuda|help)$/i,
  /^(oi|ola|olá|bom dia|boa tarde|boa noite|eae|eai|opa)$/i
];

const isSafePattern = SAFE_PATTERNS.some(pattern => pattern.test(text));

const NEEDS_LLM_PATTERNS = [
  /pizza|sabor|calabresa|mussarela|frango|queijo|portuguesa/i,
  /rua|avenida|av\.|numero|nº|bairro|casa|apt|apto|apartamento/i,
  /^[a-záéíóúàâêôãõç\s]+\s+\d{2,5}/i,
  /sem\s|tirar\s|adicionar|extra|com\s/i,
  /\s\/\s/,
  /tbm|tb|tmb|tbem|também|outra|mais uma/i,
  /meio|metade|meia|1\/2/i
];

const needsLLM = !isSafePattern && (
  messagesCount > 1 || 
  NEEDS_LLM_PATTERNS.some(pattern => pattern.test(text)) ||
  text.split(' ').length > 3
);

let reason = 'safe_pattern';
if (needsLLM) {
  if (messagesCount > 1) reason = 'multi_message';
  else if (/rua|avenida|bairro|\d{4,5}/i.test(text)) reason = 'address_freeform';
  else if (/pizza|sabor|calabresa|queijo/i.test(text)) reason = 'order_text';
  else reason = 'human_text';
}

return [{
  json: {
    ...data,
    routing: {
      used_llm: needsLLM,
      reason: reason,
      text_analyzed: text,
      word_count: text.split(' ').length,
      messages_count: messagesCount
    }
  }
}];

// ===========================================
// NODE 5: MONTAR CONTEXTO PARA LLM
// ===========================================

// Pega dados do merge (combina bairros + produtos)
const items = $input.all();
let neighborhoodsData = {};
let productsData = {};

// Identifica qual item é qual
for (const item of items) {
  if (item.json.neighborhoods) {
    neighborhoodsData = item.json;
  }
  if (item.json.products) {
    productsData = item.json;
  }
}

// Pega dados do router (anterior ao branch)
const routerData = $('Router Rules-First').first().json;

// Formata lista de bairros
const neighborhoods = neighborhoodsData.neighborhoods || [];
const neighborhoodList = neighborhoods.map(n => n.name).join(', ');

// Formata cardápio
const products = productsData.products || [];
const productList = products.map(p => `${p.name} (R$ ${p.price})`).join(', ');

const text = routerData.buffer?.combined_text || routerData.normalized.text;

return [{
  json: {
    ...routerData,
    llm_context: {
      text: text,
      neighborhoods: neighborhoodList,
      products: productList,
      neighborhoods_raw: neighborhoods,
      products_raw: products
    }
  }
}];

// ===========================================
// NODE 6: PARSE E VALIDAR RESPOSTA LLM
// ===========================================

const contextData = $('Montar Contexto LLM').first().json;
const llmResponse = $input.first().json;

let parsed = null;
let validationError = null;
let valid = false;

try {
  const content = llmResponse.choices?.[0]?.message?.content || '';

  let jsonStr = content.trim();
  if (jsonStr.startsWith('```json')) {
    jsonStr = jsonStr.replace(/```json\n?/, '').replace(/\n?```$/, '');
  } else if (jsonStr.startsWith('```')) {
    jsonStr = jsonStr.replace(/```\n?/, '').replace(/\n?```$/, '');
  }

  parsed = JSON.parse(jsonStr);

  if (!parsed.intent) {
    validationError = 'missing_intent';
  } else if (!parsed.entities) {
    validationError = 'missing_entities';
  } else if (typeof parsed.confidence !== 'number') {
    parsed.confidence = 0.5;
  }

  if (!validationError) {
    valid = true;
    parsed.raw_text = contextData.llm_context.text;
  }

} catch (e) {
  validationError = `json_parse_error: ${e.message}`;
  parsed = null;
}

return [{
  json: {
    ...contextData,
    llm: {
      provider: 'groq',
      model: 'llama-3.3-70b-versatile',
      valid: valid,
      validation_error: validationError,
      result: parsed,
      raw_response: llmResponse
    }
  }
}];

// ===========================================
// NODE 7: MATCH DE BAIRRO (FUZZY)
// ===========================================

const data = $input.first().json;
const llmResult = data.llm?.result;
const neighborhoodsRaw = data.llm_context?.neighborhoods_raw;

if (!llmResult?.entities?.address?.neighborhood_text) {
  return [{
    json: {
      ...data,
      address_resolution: {
        neighborhood_input: null,
        matched_neighborhood: null,
        match_score: 0,
        delivery_fee: null,
        candidates: [],
        status: 'no_address'
      }
    }
  }];
}

const inputNeighborhood = llmResult.entities.address.neighborhood_text;

function normalize(str) {
  return (str || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, '')
    .trim();
}

function similarity(s1, s2) {
  const n1 = normalize(s1);
  const n2 = normalize(s2);

  if (n1 === n2) return 100;
  if (n1.includes(n2) || n2.includes(n1)) return 90;

  const words1 = n1.split(/\s+/);
  const words2 = n2.split(/\s+/);
  const common = words1.filter(w => words2.some(w2 => w2.includes(w) || w.includes(w2)));
  const wordScore = (common.length / Math.max(words1.length, words2.length)) * 100;

  const len1 = n1.length;
  const len2 = n2.length;
  const maxLen = Math.max(len1, len2);

  let distance = 0;
  for (let i = 0; i < maxLen; i++) {
    if (n1[i] !== n2[i]) distance++;
  }
  const levenScore = ((maxLen - distance) / maxLen) * 100;

  return Math.max(wordScore, levenScore);
}

const neighborhoods = neighborhoodsRaw || [];

const candidates = neighborhoods
  .map(n => ({
    name: n.name,
    fee: n.fee || 0,
    score: similarity(inputNeighborhood, n.name)
  }))
  .sort((a, b) => b.score - a.score)
  .slice(0, 5);

const bestMatch = candidates[0];

let status, matchedNeighborhood, deliveryFee;

if (bestMatch && bestMatch.score >= 90) {
  status = 'matched';
  matchedNeighborhood = bestMatch.name;
  deliveryFee = bestMatch.fee;
} else if (bestMatch && bestMatch.score >= 75) {
  status = 'needs_confirmation';
  matchedNeighborhood = null;
  deliveryFee = null;
} else {
  status = 'not_found';
  matchedNeighborhood = null;
  deliveryFee = null;
}

return [{
  json: {
    ...data,
    address_resolution: {
      neighborhood_input: inputNeighborhood,
      matched_neighborhood: matchedNeighborhood,
      match_score: bestMatch?.score || 0,
      delivery_fee: deliveryFee,
      candidates: candidates.slice(0, 3),
      status: status
    }
  }
}];

// ===========================================
// NODE 8: MONTAR ENVELOPE FINAL (COM LLM)
// ===========================================

const data = $input.first().json;

const envelope = {
  source: 'n8n',
  normalized: data.normalized,
  buffer: {
    combined_text: data.buffer?.combined_text || data.normalized.text,
    messages_count: data.buffer?.messages_count || 1,
    window_seconds: data.buffer?.window_seconds || 10,
    texts: data.buffer?.texts || [data.normalized.text]
  },
  routing: data.routing,
  llm: {
    provider: data.llm?.provider || null,
    model: data.llm?.model || null,
    valid: data.llm?.valid || false,
    validation_error: data.llm?.validation_error || null,
    result: data.llm?.result || null
  },
  address_resolution: data.address_resolution || {
    neighborhood_input: null,
    matched_neighborhood: null,
    match_score: 0,
    delivery_fee: null,
    candidates: [],
    status: 'not_applicable'
  }
};

return [{ json: envelope }];

// ===========================================
// NODE 8B: MONTAR ENVELOPE FINAL (SEM LLM)
// ===========================================

const data = $input.first().json;

const envelope = {
  source: 'n8n',
  normalized: data.normalized,
  buffer: {
    combined_text: data.buffer?.combined_text || data.normalized.text,
    messages_count: data.buffer?.messages_count || 1,
    window_seconds: data.buffer?.window_seconds || 10,
    texts: data.buffer?.texts || [data.normalized.text]
  },
  routing: {
    used_llm: false,
    reason: data.routing?.reason || 'safe_pattern'
  },
  llm: null,
  address_resolution: null
};

return [{ json: envelope }];
